package com.cooreo.sippy.ui.theme

/**
 * The backdrop, measured (round 9, 1.1).
 *
 * Generated by `sippy/tools/backdrop_stats.py`, which composites the dark-theme
 * scrim over the real art and reports the mean colour and the brightest colours
 * covering 5% of the pixels. The contrast test checks every text/surface pair
 * against [BRIGHTEST_HEX] — the worst background any label can ever sit on — so the
 * rules are tied to the art instead of to a guess.
 *
 * Re-run the tool and paste the output here whenever the backdrop or the scrim
 * changes.
 */
object BackdropSamples {

    /** The scrim, as [com.cooreo.sippy.ui.glass] draws it: navy, 35% to 75%. */
    const val SCRIM_TOP_ALPHA = 0.35f
    const val SCRIM_BOTTOM_ALPHA = 0.75f

    /** Mean colour of the scrimmed backdrop, and its relative luminance. */
    const val MEAN_HEX = 0x244B65
    const val MEAN_LUMINANCE = 0.0639f

    /** The brightest colours covering 5% of the scrimmed backdrop. */
    const val BRIGHTEST_HEX = 0x85A5AD
    const val BRIGHTEST_LUMINANCE = 0.348f

    /** The second brightest, kept for the shadow-side checks. */
    const val BRIGHTEST_2_HEX = 0x709AA4
    const val BRIGHTEST_2_LUMINANCE = 0.2939f
}
